CREATE TABLE artifacts (id TEXT PRIMARY KEY, project_id TEXT REFERENCES projects(id) ON DELETE SET NULL, title TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('markdown','code','text','html','svg','mermaid')), language TEXT NOT NULL DEFAULT '', head_revision_id TEXT NOT NULL REFERENCES artifact_revisions(id) DEFERRABLE INITIALLY DEFERRED, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, origin_conversation_id TEXT REFERENCES conversations(id) ON DELETE SET NULL, origin_message_id TEXT REFERENCES messages(id) ON DELETE SET NULL, forked_from_revision_id TEXT REFERENCES artifact_revisions(id) ON DELETE SET NULL);
CREATE TABLE artifact_revisions (id TEXT PRIMARY KEY, artifact_id TEXT NOT NULL REFERENCES artifacts(id) ON DELETE CASCADE, number INTEGER NOT NULL, parent_revision_id TEXT REFERENCES artifact_revisions(id), source TEXT NOT NULL, author TEXT NOT NULL CHECK(author IN ('user','model')), source_message_id TEXT REFERENCES messages(id) ON DELETE SET NULL, created_at TEXT NOT NULL, UNIQUE(artifact_id,number));
CREATE TABLE artifact_drafts (artifact_id TEXT PRIMARY KEY REFERENCES artifacts(id) ON DELETE CASCADE, base_revision_id TEXT NOT NULL REFERENCES artifact_revisions(id), source TEXT NOT NULL, generation INTEGER NOT NULL, source_message_id TEXT REFERENCES messages(id) ON DELETE SET NULL, updated_at TEXT NOT NULL);
CREATE TABLE artifact_revision_assets (revision_id TEXT NOT NULL REFERENCES artifact_revisions(id) ON DELETE CASCADE, asset_id TEXT NOT NULL REFERENCES assets(id), PRIMARY KEY(revision_id,asset_id));
CREATE TABLE message_artifacts (message_id TEXT NOT NULL REFERENCES messages(id) ON DELETE CASCADE, artifact_id TEXT NOT NULL REFERENCES artifacts(id) ON DELETE CASCADE, revision_id TEXT NOT NULL REFERENCES artifact_revisions(id), relation TEXT NOT NULL CHECK(relation IN ('created','context','proposal')), PRIMARY KEY(message_id,revision_id,relation));
CREATE INDEX artifacts_project ON artifacts(project_id,updated_at DESC);
CREATE INDEX artifacts_messages ON message_artifacts(artifact_id,revision_id);
